765	func TestRejectedHealthKeepsHealthyInstanceEligible(t *testing.T) {
766		// A healthy instance that receives a stale or same-sequence conflicting
767		// "unhealthy" report keeps its accepted observation: the rejections state
768		// the reason and the accepted sequence, and the instance stays in the
769		// candidate set. The rejected reports target b, the instance the rotation
770		// would choose next; the cursor must neither skip it nor restart.
