775			{"type":"select","service":"svc","expectedRevision":1},
776			{"type":"health","service":"svc","instanceId":"b","expectedRevision":1,"sequence":3,"healthy":false,"reason":"flapping"},
777			{"type":"health","service":"svc","instanceId":"b","expectedRevision":1,"sequence":7,"healthy":false,"reason":"flapping"},
778			{"type":"select","service":"svc","expectedRevision":1},
779			{"type":"select","service":"svc","expectedRevision":1}
